async function makeProviderRequest(provider) {
  return new Promise((resolve, reject) => {
    const req = https.request(provider.url, provider.options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => resolve(data));
    });
    req.on('error', reject);
    req.end();
  });
}

