// Example: handling HTTP response
function handleResponse(response, providerName) {
  let body = '';
  response.on('data', chunk => body += chunk);
  response.on('end', () => {
    if (response.statusCode >= 200 && response.statusCode < 300) {
      return { success: true, provider: providerName, body: JSON.parse(body) };
    } else {
      return { success: false, provider: providerName, error: 'Request failed' };
    }
  });
}

